    "content": "export function GET() {\n  return new Response(\"google.com, pub-7151625151498067, DIRECT, f08c47fec0942fa0\\n\", {\n    headers: {\n      \"Cache-Control\": \"public, max-age=300\",\n      \"Content-Type\": \"text/plain; charset=utf-8\",\n    },\n  });\n}\n"
